use gba_core::{Machine,ffta_battle_mouse as mouse};
fn main(){let mut m=Machine::new(std::fs::read(std::env::args().nth(1).unwrap()).unwrap());for(n,d)in[("ewram",&mut m.bus.ewram),("iwram",&mut m.bus.iwram),("vram",&mut m.bus.vram),("io",&mut m.bus.io),("oam",&mut m.bus.oam),("palette",&mut m.bus.palette)]{d.copy_from_slice(&std::fs::read(format!("target/battle-current-{n}.bin")).unwrap());}m.bus.ffta_movement.enabled=true;m.bus.ffta_movement.europe_profile=true;m.bus.ffta_dialogue.separate=true;m.bus.ffta_battle_mouse.enable_replay();gba_core::mem::set_extra(22);for y in 0..160{gba_core::ppu::render_scanline(&mut m.bus,y);}for t in [0,3,1,2]{assert!(mouse::menu_select(&mut m.bus,t,false));assert_eq!(mouse::MenuScene::read(&m.bus).unwrap().selected,t);assert_eq!(mouse::keys(&mut m.bus,0x3ff),0x3ff);m.bus.ffta_battle_mouse.cancel();println!("BATTLE_DIRECT target={t} no_direction_keys=true");}
for(current,target)in[(1u16,8u16),(4,8),(8,8),(8,0),(1,0)]{m.bus.ewram[0x2dda4..0x2dda6].copy_from_slice(&current.to_le_bytes());m.bus.ewram[0x2dda8..0x2ddaa].copy_from_slice(&target.to_le_bytes());for y in 0..160{gba_core::ppu::render_scanline(&mut m.bus,y);}let ui=gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue);assert_eq!(ui.nodes[0].unwrap().bounds,[0,48,160,160]);assert_eq!(ui.nodes[1].unwrap().bounds,[168,64,240,160]);println!("BATTLE_ANIMATION current={current} target={target} fixed_bounds=true");}
println!("MENU {:?} GRID {:?} UI {:?}",mouse::MenuScene::read(&m.bus),mouse::Scene::read(&m.bus).map(|s|s.selected),gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue));}
